SET NAMES utf8mb4;

-- 1. CẬP NHẬT NGÀY TẠO KHÓA HỌC ĐỂ ĐẢM BẢO CREATED_AT CỦA KHÓA TRƯỚC MỌI ĐƠN HÀNG
UPDATE courses SET created_at = '2024-06-01 08:00:00' WHERE id BETWEEN 1 AND 8;
UPDATE courses SET created_at = '2024-10-15 08:00:00' WHERE id BETWEEN 9 AND 25;
UPDATE courses SET created_at = '2025-02-20 08:00:00' WHERE id BETWEEN 26 AND 45;

-- 2. THÊM 45 HỌC VIÊN MỚI (student04 -> student48) VỚI BCRYPT CỦA student123
ON DUPLICATE KEY UPDATE id=id;

-- 3. THÊM CÁC ĐƠN HÀNG MỚI (DÙNG INSERT ... SELECT TRA CỨU THEO EMAIL)

-- 4. THÊM CHI TIẾT ĐƠN HÀNG (ORDER_ITEMS) THEO ORDER_CODE VÀ SLUG

-- 5. THÊM GHI DANH (ENROLLMENTS) CHO CÁC ĐƠN COMPLETED

-- Đảm bảo toàn bộ order_item COMPLETED đều có enrollment tương ứng
SELECT o.user_id, oi.course_id, COALESCE(o.paid_at, o.created_at), 0.00, 0
FROM orders o
JOIN order_items oi ON o.id = oi.order_id
LEFT JOIN enrollments e ON e.user_id = o.user_id AND e.course_id = oi.course_id
WHERE o.status = 'COMPLETED' AND e.id IS NULL;
